document.querySelectorAll('[data-filter]').forEach(button=>{button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(item=>{const active=item===button;item.classList.toggle('active',active);item.setAttribute('aria-pressed',String(active));});document.querySelectorAll('[data-category]').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter;});});});
document.getElementById('copy-email').addEventListener('click',async()=>{const status=document.getElementById('copy-status');try{await navigator.clipboard.writeText('energizer629@naver.com');status.textContent='이메일 주소를 복사했습니다.';}catch{status.textContent='이 주소를 선택해 복사해주세요: energizer629@naver.com';}});
document.getElementById('year').textContent=new Date().getFullYear();
